-- READ-ONLY audit of applied/reverted history and existing proposal rows over the source-only timestamp union.
WITH u AS (SELECT a.dateTime ts FROM old_weewx.archive a LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime WHERE a.dateTime>=UNIX_TIMESTAMP('2009-01-01') AND a.dateTime<UNIX_TIMESTAMP('2021-01-01') AND r.dateTime IS NULL UNION SELECT a.dateTime ts FROM weewx_WH1080.archive a LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime WHERE a.dateTime>=UNIX_TIMESTAMP('2009-01-01') AND a.dateTime<UNIX_TIMESTAMP('2021-01-01') AND r.dateTime IS NULL)
SELECT YEAR(FROM_UNIXTIME(u.ts)) utc_year,c.variable,c.state,COUNT(*) change_events,COUNT(DISTINCT c.target_time) unique_target_times FROM u JOIN loucka_reconstruction.reconstruction_changes c ON c.target_time=u.ts GROUP BY utc_year,c.variable,c.state ORDER BY utc_year,c.variable,c.state;
-- Existing proposals are kept separate from applied history; state comes from reconstruction_batches.
WITH u AS (SELECT a.dateTime ts FROM old_weewx.archive a LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime WHERE a.dateTime>=UNIX_TIMESTAMP('2009-01-01') AND a.dateTime<UNIX_TIMESTAMP('2021-01-01') AND r.dateTime IS NULL UNION SELECT a.dateTime ts FROM weewx_WH1080.archive a LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime WHERE a.dateTime>=UNIX_TIMESTAMP('2009-01-01') AND a.dateTime<UNIX_TIMESTAMP('2021-01-01') AND r.dateTime IS NULL)
SELECT c.batch_id,c.target_time,c.source_database,c.source_time,c.source_variable,c.variable,c.source_unit,c.target_unit,c.source_value,c.proposed_value,c.rule,c.rule_version,c.reason,c.created_at,b.state batch_state,b.payload_hash,b.candidate_count FROM u JOIN loucka_reconstruction.reconstruction_candidates c ON c.target_time=u.ts JOIN loucka_reconstruction.reconstruction_batches b ON b.batch_id=c.batch_id;
